# situ capability map v1
# schema: settings_registry.situ
# core:   offset size align repr atomic
#
# Core axes are always shown. Any other axis appears only where it has
# been weakened below its strongest value.
#
# Offsets are byte values, or byte:bit where a field does not start on
# a byte boundary. Sizes are bytes unless suffixed with `bit`.
#
# A struct's size is a bare number where it is fixed, `min..max` where
# it is bounded, and `min..` where nothing bounds it.

struct address size=2.. access=Sequential mutate=Shifting address=Unstable repr=TextConverted atomic=NonAtomic
  address.lead                           offset=AbsoluteStatic(0x00) size=Fixed(1) align=Aligned(8) repr=MemoryIdentical atomic=NonAtomic
  address.host                           offset=AbsoluteStatic(0x01) size=Bounded(1, 252) align=Aligned(1) repr=MemoryIdentical atomic=AtomicWord mutate=Shifting
  address.port                           offset=Scanned size=Unbounded align=Unaligned repr=TextConverted atomic=NonAtomic access=Sequential mutate=Shifting address=Unstable

struct count size=0.. mutate=Shifting repr=TextConverted
  count.value                            offset=AbsoluteStatic(0x00) size=Unbounded align=Aligned(8) repr=TextConverted atomic=AtomicWord mutate=Shifting

struct duration size=1.. mutate=Shifting address=Unstable repr=TextConverted atomic=NonAtomic
  duration.count                         offset=AbsoluteStatic(0x00) size=Unbounded align=Aligned(8) repr=TextConverted atomic=AtomicWord mutate=Shifting
  duration.unit                          offset=Dynamic size=Fixed(1) align=Unaligned repr=MemoryIdentical atomic=NonAtomic address=Unstable
  duration.value                         let u64 = count * ((unit == time_unit.d) * 86400 + (unit == time_unit.h) * 3600 + (unit == time_unit.m) * 60 + (unit == time_unit.s))

struct flag size=0.. mutate=Shifting
  flag.word                              offset=AbsoluteStatic(0x00) size=Unbounded align=Aligned(8) repr=MemoryIdentical atomic=AtomicWord mutate=Shifting
  flag.value                             let u8 = word == flag_word.on | word == flag_word.one

struct text size=0.. mutate=Shifting
  text.bytes                             offset=AbsoluteStatic(0x00) size=Unbounded align=Aligned(8) repr=MemoryIdentical atomic=AtomicWord mutate=Shifting
